async function loadConversations(offset=0){const sequence=++listSequence;const data=await api('/api/conversations?'+new URLSearchParams({q:chatQuery,kind:chatKind,offset,limit:100}));if(route!=='chat'||sequence!==listSequence)return;if(!offset)chats=[];chats.push(...data.items);$('#conversation-list').innerHTML=chats.map(c=>`<button class="conversation ${currentChat?.id===c.id?'active':''}" data-chat="${e(c.id)}">${avatar(c.title,c.avatar,c.kind==='group'?'group-avatar':'')}<div class="conversation-body"><div class="conversation-head"><b>${e(c.title)}</b><time>${day(c.last_ts)}</time></div><p>${e(c.preview||'打开聊天记录')}</p></div></button>`).join('')||'<div class="empty-inline">没有找到会话</div>';$('#chat-pagination').innerHTML=chats.length<data.total?btn('加载更多会话','more-chats','ghost small'): `<span>共 ${num(data.total)} 段对话</span>`;}
