async function loadContacts(){const sequence=++requestSequence;const data=await api('/api/contacts?'+new URLSearchParams({q:contactsQuery,offset:contactsPage*40,limit:40}));if(route!=='contacts'||sequence!==requestSequence)return;contactRows=data.items;$('#contact-count').textContent=`共 ${num(data.total)} 位联系人${contactSelection.size?' · 已选 '+contactSelection.size+' 位':''}`;$('#contact-rows').innerHTML=data.items.map(c=>`<tr><td><input type="checkbox" data-contact="${e(c.username)}" ${contactSelection.has(c.username)?'checked':''} aria-label="选择${e(c.nickname||c.username)}"></td><td><div class="contact-name">${avatar(c.nickname||c.username,c.avatar)}<span>${e(c.nickname||c.username)}</span></div></td><td>${e(c.remark||'—')}</td><td title="${e(c.username)}">${e(c.alias||c.username)}</td><td><span class="pill ${c.kind==='direct'?'':'offline'}">${{direct:'个人联系人',group:'群聊',official:'公众号'}[c.kind]||'联系人'}</span></td></tr>`).join('')||'<tr><td colspan="5" style="text-align:center;padding:50px">没有找到联系人</td></tr>';$('#contact-pagination').innerHTML=`<span>第 ${data.total?contactsPage+1:0} / ${Math.ceil(data.total/40)} 页</span>${btn('上一页','contacts-prev','small','',''+(contactsPage?'':'disabled'))}${btn('下一页','contacts-next','small','',((contactsPage+1)*40<data.total?'':'disabled'))}`;}
const formatInfo=[['html','HTML','还原聊天，交互浏览'],['docx','Word','便于整理与打印'],['txt','TXT','轻量纯文本归档'],['csv','CSV','方便检索与分析'],['sqlite','SQLite','完整结构化消息'],['emoji','表情包','原文件与可点击图库'],['contacts','联系人','独立通讯录 CSV']];
async function renderExport(){await getAllChats();$('#content').innerHTML=`<div class="page">${heading('导出中心','选择格式、时间范围和会话，将聊天记录保存到本机。')}<div class="export-grid"><div><section class="panel export-panel"><h2 class="step-heading"><i>1</i> 选择导出格式</h2><div class="format-grid">${formatInfo.map(([id,label,desc])=>`<label class="format-card ${exportFormats.has(id)?'selected':''}"><input type="checkbox" data-format="${id}" ${exportFormats.has(id)?'checked':''}><span class="format-symbol">${id==='contacts'?'ID':id.toUpperCase().slice(0,4)}</span><b>${label}</b><small>${desc}</small></label>`).join('')}</div></section><section class="panel export-panel"><h2 class="step-heading"><i>2</i> 选择时间范围</h2><div class="date-fields"><input type="date" id="export-start" aria-label="导出起始日期"><span>至</span><input type="date" id="export-end" aria-label="导出结束日期"></div><p class="path-label">不选日期则导出全部时间；结束日期包含当天。</p><label class="export-options"><input type="checkbox" id="export-media" checked><span>包含已恢复的图片、语音、视频与文件<small>同时保存媒体和可点击浏览的 HTML 阅读器。请保留整个导出文件夹；缺失附件会注明。</small></span></label></section><section class="panel export-panel"><h2 class="step-heading"><i>3</i> 选择保存位置</h2><div class="setting-path"><input id="export-path" value="${e(state.settings.output_dir)}" aria-label="导出目录">${btn('选择文件夹','browse-output','','folder')}</div><p class="path-label">每次导出会新建独立文件夹，不覆盖此前的归档。</p></section></div><aside><section class="panel"><div class="section-heading"><h2>选择聊天</h2><span class="muted">${num(stats.conversations)} 段</span></div><div class="search-box">${icon('search')}<input id="export-search" placeholder="搜索会话" aria-label="搜索要导出的会话"></div><label class="selection-controls"><input type="checkbox" id="export-all" ${exportAll?'checked':''}>全部会话</label><div class="selection-list" id="export-conversations"></div><div class="export-summary" id="export-summary"></div>${btn('开始导出','start-export','primary export-submit','export')}</section></aside></div><section class="history-list"><div class="section-heading"><h2>最近导出记录</h2></div><div id="export-history"></div></section></div>`;renderExportChoices();renderHistory();}
function renderExportChoices(q=''){if(!$('#export-conversations'))return;$('#export-conversations').innerHTML=allChats.filter(c=>(c.title+c.id).toLowerCase().includes(q.toLowerCase())).map(c=>`<label class="selection-row"><input type="checkbox" data-export-chat="${e(c.id)}" ${exportAll||exportSelection.has(c.id)?'checked':''}>${avatar(c.title)}<span>${e(c.title)}</span></label>`).join('')||'<div class="empty-inline">没有匹配的会话</div>';exportSummary();}
function exportSummary(){if($('#export-summary'))$('#export-summary').innerHTML=`已选择 <b>${exportAll?num(stats.conversations):exportSelection.size}</b> 段对话<br>导出为 <b>${[...exportFormats].map(f=>formatInfo.find(x=>x[0]===f)?.[1]).join('、')||'尚未选择格式'}</b>`;}
function renderHistory(){if(!$('#export-history'))return;const jobs=state.jobs.filter(j=>j.kind==='export'&&j.account_id===state.selected).reverse();$('#export-history').innerHTML=jobs.map(j=>`<div class="history-row">${icon(j.status==='done'?'check':'clock')}<div><b>${j.status==='done'?'导出已完成':j.status==='error'?'导出失败':j.status==='cancelled'?'导出已取消':'正在导出'}</b><p>${e(j.result?.path||j.message)}</p></div>${btn(j.status==='done'?'打开文件夹':'查看详情',j.status==='done'?'open-job':'job-detail','small','',`data-job="${j.id}"`)}</div>`).join('')||'<div class="empty-inline">导出完成后，可以从这里打开保存的文件。</div>';}
async function renderReport(){await getAllChats();const years=stats.years,latest=reportJob?.result?.report?.year||years[0]||new Date().getFullYear();$('#content').innerHTML=`<div class="page">${heading('年度回顾','按年份查看消息统计，生成个人或双人报告。')}<div class="report-intro"><div><div class="eyebrow">A YEAR WORTH REMEMBERING</div><h2>选择年份与回顾范围</h2><p>统计消息、字数、连续聊天与常用词。<br>同时生成 HTML 与高清 PNG 图片。</p></div><div class="year-art"><span>${latest}</span></div></div><div class="report-controls"><label class="field-label">选择年份<select id="report-year">${years.map(y=>`<option value="${y}" ${y===latest?'selected':''}>${y} 年</option>`).join('')}</select></label><label class="field-label wide">回顾范围<select id="report-contact"><option value="">个人年度回顾 · 全部对话</option>${allChats.filter(c=>c.kind==='direct').map(c=>`<option value="${e(c.id)}">双人回顾 · 我和${e(c.title)}</option>`).join('')}</select></label>${btn('生成年度回顾','generate-report','primary','spark',years.length?'':'disabled')}</div><div id="report-output">${reportJob&&reportJob.account_id===state.selected&&reportJob.result?reportPreview(reportJob):'<div class="report-placeholder"><div class="notebook-mark">✳</div><h3>尚未生成年度报告</h3><p>真实消息统计 · 活跃日历 · 高频词 · 双人互动 · 手机扫码查看</p></div>'}</div></div>`;}
function reportPreview(job){const d=job.result.report,max=Math.max(...d.months,1);return `<div class="stat-grid">${statCard('这一年说过',num(d.total),'句话','chat','来自实际归档消息')}${statCard('文字总量',num(d.characters),'字','file','非空白字符，含标点')}${statCard('收到回应',num(d.received),'条','chat','来自世界的回响')}${statCard('有对话的日子',num(d.days),'天','calendar','平凡日子里的热闹')}</div><div class="report-results"><div class="panel"><div class="section-heading"><h2>十二个月的对话</h2><span class="muted">${d.year}</span></div><div class="mini-bars">${d.months.map((n,i)=>`<div class="mini-col"><i style="height:${Math.max(2,115*n/max)}px" title="${i+1}月 · ${num(n)} 条"></i><small>${String(i+1).padStart(2,'0')}</small></div>`).join('')}</div></div><div class="panel"><div class="section-heading"><h2>常挂在嘴边的话</h2></div><div class="report-words">${d.words.slice(0,18).map((w,i)=>`<span style="font-size:${11+Math.sqrt(w.count/(d.words[0]?.count||1))*13}px" title="出现 ${num(w.count)} 次">${e(w.word)}</span>`).join('')||'<p class="muted">文本不足以生成高频词</p>'}</div></div></div><div class="report-actions">${job.result.image?btn('打开年报图片','open-report-image','','file',`data-job="${job.id}"`):''}${btn('打开完整年报','open-report','','eye',`data-job="${job.id}"`)}${btn('手机扫码查看','share-report','primary','qr',`data-job="${job.id}"`)}</div>`;}
function renderSettings(){const s=state.settings;$('#content').innerHTML=`<div class="page">${heading('设置','管理保存位置、微信连接与媒体恢复。',btn('保存设置','save-settings','primary','check'))}<section class="panel settings-section"><h2>本地保存</h2><div class="setting-row"><div><label for="settings-auto-emoji">浏览时自动补全表情</label><p>仅访问消息自带的微信表情下载地址，成功后保存本地；动态表情保留动画。</p></div><input type="checkbox" class="switch" id="settings-auto-emoji" ${s.auto_emoji?'checked':''}></div><div class="setting-row stack"><label for="settings-output">默认导出目录</label><p>聊天文档与年度回顾会保存在这里，每次导出新建一个文件夹。</p><div class="setting-path"><input id="settings-output" value="${e(s.output_dir)}">${btn('选择文件夹','browse-output','','folder')}</div></div><div class="setting-row"><div><label for="settings-media">同步时恢复本地媒体</label><p>读取本机已保存的图片、视频、语音与附件；首次同步可能需要更多时间。</p></div><input type="checkbox" class="switch" id="settings-media" ${s.include_media?'checked':''}></div><div class="setting-row"><div><label>补全缺失的表情包</label><p>点击后联网访问微信表情 CDN，成功下载后保存在本机。失效链接无法恢复。</p></div>${btn('联网补全表情','restore-emoji','','refresh',account()?.has_archive?'':'disabled')}</div></section><section class="panel settings-section"><h2>微信连接</h2><div class="setting-row"><div><label for="settings-auto">自动增量更新</label><p>每秒轻量检查新消息，保留已有归档；媒体恢复在手动同步时进行。</p></div><input type="checkbox" class="switch" id="settings-auto" ${s.auto_sync?'checked':''}></div><div class="setting-row"><div><label>当前登录账号</label><p>${e(account()?.display_name||'尚未识别')} · ${account()?.active?'微信正在运行':'离线'}</p></div>${btn('重新检测','detect','','refresh')}</div><div class="setting-row stack"><label for="settings-root">微信数据目录（辅助查找）</label><p>通常自动从微信正在打开的数据库识别；自定义路径可以在这里记录。</p><div class="setting-path"><input id="settings-root" value="${e(s.data_root||account()?.root||'')}" placeholder="xwechat_files 所在目录">${btn('选择文件夹','browse-data','','folder')}</div></div><div class="setting-row"><div><label for="settings-keys">下次同步重新获取数据库密钥</label><p>微信升级、密钥失效或数据库验证失败时启用。需要微信保持登录。</p></div><input type="checkbox" class="switch" id="settings-keys" ${s.force_keys?'checked':''}></div></section><section class="panel settings-section"><h2>关于拾光</h2><div class="about-info">拾光 2.1 · Windows 微信 4.x 本地档案<br>支持聊天浏览、联系人、HTML / Word / TXT / CSV / SQLite 导出及个人、双人年度回顾。<br>支持本机媒体恢复；未下载、已删除、无法解码的附件会如实标注。WXGF 可解码时保存首帧。<br>功能设计参考 <a href="https://github.com/shixiaogaoya/MemoTrace" target="_blank" rel="noopener noreferrer">MemoTrace ↗</a>，继续使用原有 wxdump 数据库取钥能力。</div></section></div>`;}
function showModal(title,body,actions='',wide=false){modalType=modalType||'generic';$('#modal').innerHTML=`<div class="modal-card ${wide?'wide':''}"><div class="modal-top"><h2 id="modal-title">${title}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭弹窗">${icon('close')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;$('#modal').classList.remove('hidden');$('#modal [data-action="close-modal"]')?.focus();}
function closeModal(){if(modalType==='share')api('/api/share/stop',{}).catch(()=>{});$('#modal').classList.add('hidden');modalType='';}
function accountsModal(){modalType='accounts';showModal('我的微信账号',`<p class="modal-description">当前登录账号来自微信正在打开的数据库。离线账号仅用于查看已有归档。</p>${state.accounts.map(a=>`<button class="account-option ${a.id===state.selected?'selected':''}" data-account-id="${a.id}">${avatar(a.display_name)}<div><b>${e(a.display_name)}</b><small>${e(a.username)}</small></div><span class="pill ${a.active?'':'offline'}">${a.active?'当前登录':'离线归档'}</span></button>`).join('')||'<div class="empty-inline">未发现账号。请先在电脑上登录微信。</div>'}`,btn('重新检测','detect','','refresh'));}
function jobModal(id){selectedJob=id;modalType='job';updateJobModal();}
function updateJobModal(){
 const j=state.jobs.find(x=>x.id===selectedJob);if(!j)return;
 const modal=$('#modal'),same=modal.dataset.jobId===j.id&&modal.dataset.jobStatus===j.status&&!!modal.querySelector('.task-log');
 const names={sync:'正在收藏你的微信时光',legacy:'导入已有的聊天归档',export:'把聊天保存到本地',report:'正在制作年度回顾',emoji:'正在联网补全表情',moments_sync:'正在同步朋友圈',moments_export:'正在导出朋友圈',moments_repair:'正在修复朋友圈半图'};
 if(!same){
  const opened=modal.querySelector('details')?.open;
  let actions=j.status==='running'?btn('取消任务','cancel-job','danger'):btn('完成','close-modal','primary');
  if(j.status==='done'&&j.result?.path)actions=btn('打开文件夹','open-job','','folder',`data-job="${j.id}"`)+actions;
  showModal(j.status==='done'?'任务已完成':j.status==='error'?'任务暂时未能完成':j.status==='cancelled'?'任务已取消':names[j.kind],`<p class="task-status"></p><div class="progress-track"><div class="progress-fill"></div></div><p class="path-label" data-job-progress></p><p class="path-label" data-job-media></p><p class="path-label" data-job-path></p><details ${opened?'open':''}><summary>查看处理日志</summary><pre class="task-log"></pre></details>`,actions);
  modal.dataset.jobId=j.id;modal.dataset.jobStatus=j.status;
 }
 modal.querySelector('.task-status').textContent=j.message||'';
 modal.querySelector('.progress-fill').style.width=`${j.percent}%`;
 modal.querySelector('[data-job-progress]').textContent=j.status==='running'?`已完成 ${j.percent}% · 可以继续浏览已有归档`:j.result?.messages?`共整理 ${num(j.result.messages)} 条消息`:'';
 modal.querySelector('[data-job-media]').textContent=j.result?.media?`媒体：可打开 ${num(j.result.media.available)} 个，缺失 ${num(j.result.media.missing)} 个。详情见导出目录中的媒体恢复情况.json。`:'';
 modal.querySelector('[data-job-path]').textContent=j.result?.path||'';
 const log=modal.querySelector('.task-log'),bottom=log.scrollHeight-log.scrollTop-log.clientHeight<30;
 const lines=(j.logs||[]).join('\n');if(log.textContent!==lines){log.textContent=lines;if(bottom)log.scrollTop=log.scrollHeight;}
}
async function startJob(kind,options={}){if(!account()){toast('请先登录微信，再点击重新检测。');return;}const job=await api('/api/jobs',{kind,options:{...options,account_id:state.selected}});state.jobs.push({...job,status:'running'});jobModal(job.id);renderTaskbar();}
async function runInsightSkill(node,kind,cid){const accountId=state.selected;node.disabled=true;const host=node.closest('.setting-path')||node.parentElement;let box=document.createElement('div');box.className='insight-skill-progress';box.setAttribute('role','status');box.setAttribute('aria-live','polite');box.innerHTML='<progress max="100" value="0"></progress> <span>正在读取聊天记录 · 0%</span>';host.after(box);const startedAt=Date.now();try{const task=await api('/api/insights/skill/start',{kind,cid});for(;;){if(state.selected!==accountId)throw Error('登录账号已变化，当前进度已结束。');const job=await api('/api/insights/skill/'+encodeURIComponent(task.id));const bar=box.querySelector('progress'),label=box.querySelector('span');if(bar)bar.value=job.percent||0;if(label)label.textContent=`${job.stage||'正在处理'} · ${job.percent||0}% · 已用 ${Math.floor((Date.now()-startedAt)/1000)} 秒`;if(job.status==='error')throw Error(job.error||'技能生成失败。');if(job.status==='done'){if(route==='insights'&&insightCid===cid){await loadInsightSkills(cid);toast(kind==='my_style'?'风格规则已生成，可修改后保存。':'成长支持规则已生成，可修改后保存。');}return job.result;}await new Promise(resolve=>setTimeout(resolve,700));}}finally{if(node.isConnected)node.disabled=false;setTimeout(()=>box.remove(),5000);}}
function renderTaskbar(){const j=state?.jobs.find(j=>j.status==='running'&&!j.automatic);$('#taskbar').classList.toggle('hidden',!j);if(j)$('#taskbar').innerHTML=`<span class="spinner"></span><div><b>${e(j.message)}</b><small>${j.percent}% · 在后台处理手动任务</small></div>${btn('查看进度','job-detail','small','',`data-job="${j.id}"`)}`;}
let polling=false;
async function poll(){if(polling||!state)return;polling=true;try{
 const previous=new Map(state.jobs.map(j=>[j.id,j.status])),oldLive=state.live||{},fresh=await api('/api/state');state=fresh;
 if(state.live?.chat_revision!==oldLive.chat_revision&&route==='chat'&&currentChat&&!messageQuery&&!messageUntil&&!messageKind){await loadConversations();const box=$('#messages'),bottom=box&&box.scrollHeight-box.scrollTop-box.clientHeight<100;if(bottom)await loadMessages();else{const notice=$('.reader-notice');if(notice)notice.innerHTML=btn('有更新，点击查看最新消息','reset-messages','small');}}
 if(state.live?.moments_revision!==oldLive.moments_revision&&route==='moments'){await loadMoments(0);}
 for(const j of state.jobs){if(j.status==='running'||previous.get(j.id)===j.status)continue;
  if(j.status==='done'){
   if(j.kind==='report'){reportJob=j;if(route==='report')$('#report-output').innerHTML=reportPreview(j);}
   if(j.kind==='emoji')await refreshEmoji();
   if(['sync','legacy','quick_sync'].includes(j.kind)&&(!j.automatic||j.result?.new_messages||j.result?.updated_messages)){
    allChats=[];stats=await api('/api/stats');renderShell();
    if(route==='chat'&&currentChat){if(!j.automatic)await loadConversations();const box=$('#messages'),bottom=box&&box.scrollHeight-box.scrollTop-box.clientHeight<100;
     if(bottom&&!messageQuery&&!messageUntil&&!messageKind&&!j.automatic)await loadMessages();
     else if((j.result?.new_messages||j.result?.updated_messages)&&(!j.automatic||!bottom||messageQuery||messageUntil||messageKind)){const notice=$('.reader-notice');if(notice)notice.innerHTML=btn('有更新，点击查看最新消息','reset-messages','small');}
    }else if(!j.automatic)await navigate(route);
   }
   if(['moments_sync','moments_quick','moments_repair'].includes(j.kind)&&route==='moments')await renderMoments();
   if(!j.automatic&&j.kind!=='emoji')toast(j.kind==='report'?'年度回顾和图片已生成':j.message||'任务已完成');
  }else if(j.status==='error'&&!j.automatic)toast(j.message);
  renderHistory();
 }
 if(modalType==='job')updateJobModal();renderTaskbar();ensureVisibleEmoji();
 const status=$('#privacy-label');if(status)status.innerHTML=icon('lock')+(state.live?.error?'自动更新异常':state.live?.enabled?'本地 · 自动更新':'本地数据');if(status)status.title=state.live?.error||'每秒检查当前账号的新消息';
}catch(err){console.warn('任务状态暂不可用');}finally{polling=false}}
let momentOffset=0;
async function renderMoments(){momentOffset=0;$('#content').innerHTML=`<div class="page">${heading('朋友圈','浏览当前账号已归档的动态；图片会从原动态地址恢复并保存在本机。',btn('同步朋友圈','moments-sync','primary','refresh')+btn('修复半图','moments-repair','','refresh')+btn('从微信界面选择动态','moments-live','','eye')+btn('导出朋友圈','moments-export','','export'))}<div class="search-box"><input id="moments-query" placeholder="搜索文字或作者" aria-label="搜索朋友圈">${btn('搜索','moments-search','small')}</div><div id="moments-feed"></div><div id="moments-more"></div></div>`;await loadMoments(0);}
async function loadMoments(offset){const data=await api('/api/moments?'+new URLSearchParams({q:$('#moments-query')?.value||'',offset,limit:30}));if(route!=='moments')return;const feed=$('#moments-feed');if(!offset)feed.innerHTML='';feed.insertAdjacentHTML('beforeend',data.items.map(m=>MomentRenderer.card(m,asset,true)+`<div class="moment-action-row">${btn('点赞','moment-like','small','',`data-mid="${e(m.id)}"`)}${btn('评论','moment-comment','small','',`data-mid="${e(m.id)}"`)}</div>`).join(''));momentOffset=offset+data.items.length;queueMomentRestore(data.items);if(!data.total)feed.innerHTML=empty('暂无朋友圈归档','点击同步朋友圈，读取当前账号本机缓存的动态。','moments-sync','同步朋友圈','eye');$('#moments-more').innerHTML=momentOffset<data.total?btn(`加载更多 · ${momentOffset} / ${num(data.total)}`,'moments-more','small'):`<p class="muted">共 ${num(data.total)} 条缓存动态</p>`;}
const momentRestoreAttempted=new Set();
async function queueMomentRestore(items){
 const ids=items.filter(m=>(m.detail?.media||[]).some(x=>x.type==='2'&&!x.media_path)&&!momentRestoreAttempted.has(m.id)).map(m=>m.id);
 ids.forEach(id=>momentRestoreAttempted.add(id));
 for(let i=0;i<ids.length;i+=10){
  try{
   const result=await api('/api/moments/restore',{ids:ids.slice(i,i+10)});
   if(route!=='moments')return;
   for(const item of result.updated||[]){
    const button=$(`.moment-card[data-mid="${CSS.escape(item.mid)}"] [data-index="${item.index}"]`);
    const slot=button?.closest('.moment-missing');
    if(slot&&item.media_path){const src=e(asset(item.media_path));slot.outerHTML=`<a href="${src}" target="_blank" rel="noopener"><img src="${src}" loading="lazy" alt="朋友圈图片"></a>`;}else if(slot){const note=slot.querySelector("small");if(note)note.textContent=item.media_status;}
   }
  }catch(err){console.warn('朋友圈图片恢复失败',err);return;}
 }
}
