async function showLiveMoments(prefer='',draft=''){
 const data=await api('/api/automation/moments-live');modalType='moment-live';
 showModal('选择微信界面中的动态',`<p class="modal-description">列出当前微信朋友圈界面可识别的动态。图片或无文字动态可在这里按作者、时间和图片数选择；列表变化时需要刷新后重选。操作会切换微信界面。</p><textarea id="moment-live-comment" rows="2" maxlength="300" style="width:100%" placeholder="评论内容（点赞可留空）">${e(draft)}</textarea><div class="live-moment-list">${data.items.map(x=>`<div class="live-moment-row"><div><b>${e(x.publisher||'未知作者')}</b><small>${e(x.time||'时间未知')} · ${num(x.image_count)} 张图片</small><p>${e(x.text||'无文字动态')}</p></div>${btn('点赞','moment-live-like','small','','data-index="'+x.index+'" data-fingerprint="'+e(x.fingerprint)+'"')}${btn('评论','moment-live-comment','small','','data-index="'+x.index+'" data-fingerprint="'+e(x.fingerprint)+'"')}</div>`).join('')||'<p class="muted">当前微信界面没有可识别的动态。</p>'}</div>`,btn('刷新列表','moments-live','small','refresh')+btn('关闭','close-modal'));
 if(prefer==='comment')$('#moment-live-comment')?.focus();
}
async function renderAutomation(){
 const [cfg,contacts]=await Promise.all([api('/api/automation'),api('/api/contacts?limit=5000')]);
 const people=contacts.items.filter(c=>c.kind==='direct');
 $('#content').innerHTML=`<div class="page">${heading('自动回复','选择好友、回复方式与每人的提示词。',btn('设置 AI 模型','go-model','','spark'))}
 <section class="panel settings-section"><h2>监听与回复规则</h2><p class="muted">仅处理启用后新同步的消息。连续消息按设置合并，不因发送频繁而丢弃；发送状态不确定时不会自动重试。微信发送仍需窗口可交互；后台自动发送会等桌面空闲约 2 秒，完成后尝试恢复原窗口焦点，使用鼠标时不会立即抢操作。</p>
 <label class="setting-row"><span>启用自动回复</span><input id="listen-enabled" type="checkbox" class="switch" ${cfg.enabled?'checked':''}></label>
 <div class="setting-row stack"><span>回复方式</span><div class="choice-row"><label><input type="radio" name="listen-mode" value="fixed" ${cfg.mode==='fixed'?'checked':''}> 固定文字 · 最快</label><label><input type="radio" name="listen-mode" value="ai" ${cfg.mode==='ai'?'checked':''}> AI 模型 · 取决于接口速度</label></div></div>
 <div id="listen-fixed-fields" ${cfg.mode==='ai'?'hidden':''}><div class="setting-row stack"><label for="listen-reply">固定文字</label><textarea id="listen-reply" rows="3" maxlength="500" style="width:100%;margin-top:12px" placeholder="选择固定文字时发送的内容">${e(cfg.reply||'')}</textarea></div></div>
 <div id="listen-ai-fields" ${cfg.mode==='fixed'?'hidden':''}><p class="muted">当前模型：${e(cfg.model)} · ${cfg.provider_id==='ollama'?'本机服务可不填密钥':cfg.has_key?'密钥已加密保存':'当前服务商尚未保存密钥'}${state.live?.error?' · 同步异常：'+e(state.live.error):''}</p><div class="setting-row stack"><label for="listen-role">统一回复角色</label><select id="listen-role">${cfg.roles.map(r=>`<option value="${e(r.id)}" ${cfg.role_id===r.id?'selected':''}>${e(r.name)} · ${e(r.description)}</option>`).join('')}</select><p class="muted">角色决定措辞和处事风格；历史聊天只用来理解上下文，不照抄。下方可为每位好友单独选择。</p><details class="role-library"><summary>查看角色库 · ${cfg.roles.length} 种风格</summary>${cfg.roles.map(r=>`<article><b>${e(r.name)}</b><p>${e(r.details)}</p></article>`).join('')}</details></div><div class="setting-row stack"><label for="listen-context-inline">参考最近几条消息回复</label><input id="listen-context-inline" type="number" min="0" max="10" step="1" value="${num(cfg.context_turns||0)}"><p class="muted">只读取同一好友最近的 0–10 条文字；0 表示只依据新消息。模型和提示词在 AI 模型页配置。</p></div></div>
 <div class="setting-row stack"><label for="listen-batch-seconds">合并消息等待时间（0–20 秒）</label><input id="listen-batch-seconds" type="number" min="0" max="20" step="1" value="${num(cfg.batch_seconds||0)}"><p class="muted">连续消息合并为一次回复；设为 0 时立即处理。持续来信会按批次回复。</p></div>
 <label class="setting-row"><span>随机发送表情图片</span><input id="listen-random-emoji" type="checkbox" class="switch" ${cfg.random_emoji?'checked':''}></label>
 <div class="setting-row stack"><label for="listen-emoji-dir">自备表情图片文件夹</label><div class="setting-path"><input id="listen-emoji-dir" value="${e(cfg.emoji_dir||'')}" placeholder="选择含 GIF、PNG、JPG 的文件夹">${btn('选择文件夹','browse-emoji-dir','','folder')}</div><p class="muted">仅使用你放入此文件夹的图片，发送前先完成文字回复。动态 GIF 在微信中的呈现由微信决定。</p></div>
 <div class="setting-row stack"><label for="listen-emoji-probability">每次回复后发送表情的概率（0–100%）</label><input id="listen-emoji-probability" type="number" min="0" max="100" step="1" value="${num(cfg.emoji_probability??25)}"></div>
 <div class="setting-row stack"><label>选择好友 <span class="muted">最多 100 位；可单选、批量或全选</span></label><div class="setting-path">${btn('全选 / 取消全选','listen-select-all','','check')}<span id="listen-count" class="muted">已选择 ${cfg.contacts.length} 位</span></div><div class="search-box"><input id="listen-search" placeholder="搜索联系人"></div><div id="listen-contacts" class="selection-list" style="max-height:300px">${people.map(c=>`<label class="selection-row" data-listen-row="${e((c.remark||c.nickname||c.username).toLowerCase())}"><input type="checkbox" data-listen-contact="${e(c.username)}" ${cfg.contacts.includes(c.username)?'checked':''}><span>${e(c.remark||c.nickname||c.username)}</span></label>`).join('')}</div></div>
 <div class="setting-row stack" id="listen-prompts" ${cfg.mode==='fixed'?'hidden':''}><label>每位好友的专属角色与要求</label><p class="muted">先勾选好友并保存，再选择风格；专属要求可加入对两人关系的已确认事实。关系镜像生成的成长支持规则也会显示在这里。</p>${people.filter(c=>cfg.contacts.includes(c.username)).map(c=>`<label style="display:block;margin:12px 0">${e(c.remark||c.nickname||c.username)}<select data-contact-role="${e(c.username)}" style="display:block;width:100%;margin-top:6px"><option value="">使用统一角色</option>${cfg.roles.map(r=>`<option value="${e(r.id)}" ${cfg.contact_roles?.[c.username]===r.id?'selected':''}>${e(r.name)}</option>`).join('')}</select><textarea data-contact-prompt="${e(c.username)}" rows="3" maxlength="12000" style="width:100%;margin-top:6px" placeholder="这位好友的专属回复要求（可选）">${e(cfg.contact_prompts?.[c.username]||'')}</textarea></label>`).join('')||'<p class="muted">还没有选中的好友。</p>'}</div>
 <div class="setting-path">${btn('保存并应用','save-automation','primary','check')}</div></section>
 <section class="panel settings-section"><h2>处理记录</h2><div id="listen-events">${cfg.events.slice().reverse().map(x=>`<p class="muted">${e(x.time)} · ${e(x.message)}</p>`).join('')||'<p class="muted">暂无处理记录。</p>'}</div></section></div>`;
 $('#listen-search').addEventListener('input',ev=>{const q=ev.target.value.toLowerCase();$$('[data-listen-row]').forEach(n=>n.hidden=!n.dataset.listenRow.includes(q));});
}
async function renderProactive(){
 const [cfg,contacts]=await Promise.all([api('/api/automation'),api('/api/contacts?limit=5000')]);
 const people=contacts.items.filter(c=>c.kind==='direct');
 const due=new Date(Date.now()+5*60000);due.setMinutes(due.getMinutes()-due.getTimezoneOffset());
 const status={queued:'等待发送',running:'正在发送',done:'已操作发送',uncertain:'结果待确认',cancelled:'已取消'};
 $('#content').innerHTML=`<div class="page">${heading('主动消息','选多位好友，写固定文字或按主题生成各自草稿。',btn('刷新状态','proactive-refresh','','refresh'))}
 <section class="panel settings-section"><h2>选择接收人</h2><p class="muted">最多 20 位；发送前逐条预览和编辑。只有点击确认才会交给微信。</p>
 <div class="setting-path">${btn('全选 / 取消全选','proactive-select-all','','check')}</div><div class="search-box"><input id="proactive-search" placeholder="搜索好友姓名或微信号" aria-label="搜索好友"></div>
 <div class="selection-list" style="max-height:260px">${people.map(c=>`<label class="selection-row" data-proactive-row="${e((c.remark||c.nickname||c.username).toLowerCase())}"><input type="checkbox" data-proactive-contact="${e(c.username)}"><span>${e(c.remark||c.nickname||c.username)}</span></label>`).join('')}</div><p id="proactive-count" class="muted">已选择 0 位</p></section>
 <section class="panel settings-section"><h2>编写内容</h2><div class="choice-row"><label><input type="radio" name="proactive-mode" value="fixed" checked> 固定文字</label><label><input type="radio" name="proactive-mode" value="topic"> AI 主题</label></div>
 <div class="setting-row stack"><label for="proactive-message">文字或主题</label><textarea id="proactive-message" rows="4" maxlength="1000" placeholder="固定文字会用于全部好友；AI 主题会结合各自最近的聊天生成草稿"></textarea></div>
 <div class="setting-path">${btn('生成发送预览','proactive-prepare','primary','arrow')}</div><div id="proactive-preview"></div></section>
 <section class="panel settings-section"><h2>安排一次发送</h2><div class="setting-row stack"><label for="proactive-time">本地时间</label><input id="proactive-time" type="datetime-local" value="${due.toISOString().slice(0,16)}"><p class="muted">先生成固定文字预览，再为选中的好友安排一次发送。程序需保持运行。</p></div><div class="setting-path">${btn('安排已预览的消息','proactive-schedule','','clock')}</div></section>
 <section class="panel settings-section"><h2>发送计划</h2><div class="scheduled-list">${cfg.scheduled.slice().reverse().map(j=>`<div class="setting-row"><div><b>${e(j.name||j.conversation_id)}</b><p>${e(j.message)} · ${e(new Date(j.due_at*1000).toLocaleString('zh-CN'))} · ${status[j.status]||e(j.status)}${j.result?' · '+e(j.result):''}</p></div>${j.status==='queued'?btn('取消','proactive-cancel','small','','data-id="'+e(j.id)+'"'):''}</div>`).join('')||'<p class="muted">还没有发送计划。</p>'}</div></section></div>`;
 proactiveDrafts=[];
 $('#proactive-search').addEventListener('input',ev=>{const q=ev.target.value.toLowerCase();$$('[data-proactive-row]').forEach(n=>n.hidden=!n.dataset.proactiveRow.includes(q));});
}
async function renderModel(){
 const cfg=await api('/api/automation');
 modelProfiles=cfg.providers||{};
 $('#content').innerHTML=`<div class="page">${heading('AI 模型','配置回复接口、统一提示词与视觉识别。',btn('返回自动回复','go-automation','','chat'))}
 <section class="panel settings-section"><h2>模型连接</h2><div class="setting-row stack"><label for="listen-provider">服务商</label><select id="listen-provider">${Object.entries(modelProfiles).map(([id,p])=>`<option value="${e(id)}" ${id===cfg.provider_id?'selected':''}>${e(p.title)}</option>`).join('')}</select><p class="muted">各服务商的地址、模型与密钥分别保存在本机；可切换后继续编辑。</p></div><div class="setting-row stack"><label for="listen-api-url">接口地址</label><div class="setting-path"><input id="listen-api-url" value="${e(cfg.api_url||'https://api.deepseek.com')}" placeholder="https://api.deepseek.com">${btn('测试连接','test-model','','spark')}</div><p class="muted">使用兼容 /chat/completions 的接口。启用 AI 回复时会把选中好友的新消息发送到该地址。</p><p id="model-test-result" class="muted" role="status" aria-live="polite">填好地址、模型和密钥后点击测试；只发送 ping，不读取聊天记录。</p></div>
 <div class="setting-row stack"><label for="listen-model">模型名称</label><div class="setting-path"><input id="listen-model" value="${e(cfg.model||'')}" placeholder="获取列表后选择，或手动填写">${btn('在线获取模型','fetch-models','','refresh')}</div><select id="available-models" size="8" aria-label="可用模型列表" hidden></select><p id="model-list-note" class="muted">点击“在线获取模型”读取当前服务商的可用模型。</p></div>
 <div class="setting-row stack"><label for="listen-api-key">API Key</label><input id="listen-api-key" type="password" autocomplete="new-password" placeholder="${cfg.has_key?'已保存，留空保持不变':'输入 API Key'}"><p class="muted">密钥使用 Windows DPAPI 加密，单独保存在当前用户的本地应用数据目录；分享软件文件不会附带它。</p></div></section>
 <section class="panel settings-section"><h2>AI 回复要求</h2><div class="setting-row stack"><label for="listen-system">统一提示词</label><textarea id="listen-system" rows="4" maxlength="2000" style="width:100%">${e(cfg.system_prompt||'')}</textarea><p class="muted">自动回复页可以给每位好友单独覆盖此提示词。</p></div>
 <label class="setting-row"><span>告诉模型当前本地时间</span><input id="listen-time-awareness" type="checkbox" class="switch" ${cfg.time_awareness?'checked':''}></label>
 </section>
 <section class="panel settings-section"><h2>视觉识别</h2><p class="muted">需要模型支持图片输入。仅使用已恢复到本地归档的图片，单次最多 4 张；尚未恢复的媒体会跳过。</p>
 <label class="setting-row"><span>识别图片</span><input id="listen-image-recognition" type="checkbox" class="switch" ${cfg.image_recognition?'checked':''}></label>
 <label class="setting-row"><span>识别表情包</span><input id="listen-emoji-recognition" type="checkbox" class="switch" ${cfg.emoji_recognition?'checked':''}></label>
 <div class="setting-path">${btn('保存模型设置','save-model','primary','check')}</div></section></div>`;
}
async function renderInsights(){return Mirror.render();}
async function loadInsightSkills(cid){const items=await api('/api/insights/skills?'+new URLSearchParams({cid})),box=$('#insight-skills');if(!box)return;box.innerHTML=['my_style','growth_support'].map(kind=>`<div class="setting-row stack"><label for="skill-${kind}">${kind==='my_style'?'我的聊天风格技能':'成长支持回复技能'}</label><textarea id="skill-${kind}" rows="18" maxlength="12000" placeholder="生成后可在此修改并保存">${e(items[kind]||'')}</textarea><div class="setting-path">${btn('保存技能','insight-save','','check',`data-kind="${kind}"`)}${btn('导出 Markdown','insight-export-skill','','export',`data-kind="${kind}"`)}${btn('应用于已选好友','insight-apply','','arrow',`data-kind="${kind}"`)}</div></div>`).join('');}
async function renderMedia(){
 const health=await api('/api/media/health'),settings=state.settings;
 $('#content').innerHTML=`<div class="page">${heading('媒体管理','检查聊天图片与表情包的本地恢复情况。',btn('同步媒体','sync','primary','refresh'))}
 <div class="stat-grid overview-stats">${statCard('图片消息',num(health.image),'条','file','来自当前账号')}${statCard('表情包消息',num(health.emoji),'条','spark','来自当前账号')}${statCard('可打开媒体',num(health.linked),'条','check','含缩略图与首帧')}${statCard('本机尚无媒体',num(health.unavailable),'条','info','可尝试补全')}</div>
 <section class="panel settings-section"><h2>清晰度与文件检查</h2><p>仅有缩略图：<b>${num(health.thumbnail)}</b> 条；WXGF 可查看首帧：<b>${num(health.first_frame)}</b> 条。</p><p>最近检查 ${num(health.recent_checked)} 个媒体文件，文件缺失 <b>${num(health.recent_broken)}</b> 个。缩略图和首帧可查看，但不能代表原图或完整动画已保存在电脑上。</p></section>
 <section class="panel settings-section"><h2>恢复与导出</h2><label class="setting-row"><span>同步时恢复本机媒体</span><input id="media-sync" type="checkbox" class="switch" ${settings.include_media?'checked':''}></label><label class="setting-row"><span>浏览时自动补全缺失表情</span><input id="media-auto-emoji" type="checkbox" class="switch" ${settings.auto_emoji?'checked':''}></label><div class="setting-path">${btn('保存设置','save-media','primary','check')}${btn('联网补全表情','restore-emoji','','refresh')}${btn('重试失败表情','retry-emoji','','refresh')}${btn('导出表情包','export-emoji','','export')}</div></section></div>`;
}
document.addEventListener('click',async event=>{try{
 const nav=event.target.closest('[data-nav]');if(nav){await navigate(nav.dataset.nav);return;}
 const node=event.target.closest('[data-action]');if(node){if(!node.disabled)await actions[node.dataset.action]?.(node);return;}
 const chat=event.target.closest('[data-chat]');if(chat){await openChat(chat.dataset.chat);return;}
 const filter=event.target.closest('[data-chat-kind]');if(filter){chatKind=filter.dataset.chatKind;$$('[data-chat-kind]').forEach(n=>n.classList.toggle('active',n===filter));await loadConversations();return;}
 const acc=event.target.closest('[data-account-id]');if(acc){state=await api('/api/select',{id:acc.dataset.accountId});allChats=[];currentChat=null;reportJob=null;insightReport=null;insightCid='';Mirror.reset();proactiveDrafts=[];proactiveSnapshot='';contactSelection.clear();exportSelection.clear();exportAll=true;closeModal();await loadState();await navigate('home');return;}
 const ref=event.target.closest('[data-ref]');if(ref){if(!ref.dataset.ref){toast('此归档没有原消息编号。');return;}messageQuery=messageUntil=messageKind='';$('#message-search').value='';$('#message-date').value='';$('#message-kind').value='';await loadMessages(false,ref.dataset.ref);return;}
 const image=event.target.closest('.image-link');if(image){event.preventDefault();modalType='image';showModal('图片预览',`<img class="image-modal" src="${e(image.getAttribute('href'))}" alt="聊天图片">`,'',true);$('#modal .modal-card').classList.add('lightbox-card');return;}
 if(event.target===$('#modal'))closeModal();
}catch(err){toast(err.message);}});
document.addEventListener('error',event=>{const image=event.target;if(!(image instanceof HTMLImageElement)||!image.classList.contains('message-image'))return;const link=image.closest('.image-link'),src=link?.getAttribute('href');if(!link||!src)return;link.outerHTML=`<div class="missing-media"><b>媒体加载失败</b><small>本地文件可能已移动，或格式暂不支持</small>${btn('重新加载','retry-media','small','refresh',`data-src="${e(src)}"`)}</div>`;},true);
document.addEventListener('input',event=>{const t=event.target;clearTimeout(queryTimer);queryTimer=setTimeout(async()=>{try{if(t.id==='chat-search'){chatQuery=t.value;await loadConversations();}else if(t.id==='message-search'){messageQuery=t.value;await loadMessages();}else if(t.id==='contact-search'){contactsQuery=t.value;contactsPage=0;await loadContacts();}else if(t.id==='export-search')renderExportChoices(t.value);}catch(err){toast(err.message);}},200);});
document.addEventListener('change',async event=>{try{const t=event.target;if(t.name==='insight-contact'){insightCid=t.value;insightReport=null;await renderInsights();}else if(t.dataset.proactiveContact){$('#proactive-count').textContent=`已选择 ${$$('[data-proactive-contact]:checked').length} 位`;}else if(t.id==='listen-provider'){const p=modelProfiles[t.value];if(p){$('#listen-api-url').value=p.api_url||'';$('#listen-model').value=p.model||'';$('#listen-api-key').value='';$('#listen-api-key').placeholder=t.value==='ollama'?'本机 Ollama 通常无需密钥':p.has_key?'已保存，留空保持不变':'输入 API Key';$('#available-models').innerHTML='';$('#model-list-note').textContent='切换后点击“在线获取模型”，保存后才会应用。';}}else if(t.id==='report-year'){const year=$('.year-art>span');if(year)year.textContent=t.value;}else if(t.id==='message-kind'){messageKind=t.value;await loadMessages();}else if(t.dataset.format){t.checked?exportFormats.add(t.dataset.format):exportFormats.delete(t.dataset.format);t.closest('.format-card').classList.toggle('selected',t.checked);exportSummary();}else if(t.id==='export-all'){exportAll=t.checked;exportSelection.clear();renderExportChoices($('#export-search').value);}else if(t.dataset.exportChat){if(exportAll){exportAll=false;exportSelection=new Set(allChats.map(c=>c.id));$('#export-all').checked=false;}t.checked?exportSelection.add(t.dataset.exportChat):exportSelection.delete(t.dataset.exportChat);exportSummary();}else if(t.dataset.contact){t.checked?contactSelection.add(t.dataset.contact):contactSelection.delete(t.dataset.contact);$('#contact-count').textContent=`已选择 ${contactSelection.size} 位联系人`;}else if(t.id==='contact-all'){contactRows.forEach(c=>t.checked?contactSelection.add(c.username):contactSelection.delete(c.username));$$('[data-contact]').forEach(n=>n.checked=t.checked);$('#contact-count').textContent=`已选择 ${contactSelection.size} 位联系人`;}}catch(err){toast(err.message);}});
document.addEventListener('change',event=>{const t=event.target;if(t.name==='listen-mode'){$('#listen-fixed-fields').hidden=t.value!=='fixed';$('#listen-ai-fields').hidden=t.value!=='ai';$('#listen-prompts').hidden=t.value!=='ai';}else if(t.dataset.listenContact){$('#listen-count').textContent=`已选择 ${$$('[data-listen-contact]:checked').length} 位`;}else if(t.id==='available-models'){actions['choose-model']();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Enter'&&event.ctrlKey&&event.target.id==='chat-compose-text'){event.preventDefault();actions['send-chat']($('[data-action="send-chat"]')).catch(err=>toast(err.message));return;}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();navigate('chat').then(()=>$('#chat-search')?.focus());}if(event.key==='Tab'&&!$('#modal').classList.contains('hidden')){const nodes=$$('#modal button:not(:disabled),#modal input,#modal a,#modal summary');if(nodes.length){if(event.shiftKey&&document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1).focus();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0].focus();}}}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1)||'home';if(next!==route)navigate(next).catch(err=>toast(err.message));});
if(window.qt?.webChannelTransport){const script=document.createElement('script');script.src='qrc:///qtwebchannel/qwebchannel.js';script.onload=()=>new QWebChannel(qt.webChannelTransport,channel=>{native=channel.objects.native;native.folderSelected.connect((kind,path)=>{const input=kind==='article_output'?$('#article-output'):kind==='article_cache'?$('#article-cache_root'):kind==='archive_dir'?$('#settings-archive'):kind==='emoji_dir'?$('#listen-emoji-dir'):kind==='data_root'?$('#settings-root'):$('#settings-output')||$('#export-path');if(input)input.value=path;});if(native.yuanbaoSessionChanged)native.yuanbaoSessionChanged.connect(ready=>window.dispatchEvent(new CustomEvent('yuanbao-session',{detail:{ready}})));});document.head.append(script);}
(async()=>{try{await loadState();await navigate(location.hash.slice(1)||'home');setInterval(poll,1000);}catch(err){$('#content').innerHTML=empty('暂时无法打开时光馆',e(err.message),'detect','重新检测');}})();

let momentPicker=null;
async function showMomentImages(mid,index,offset=0){const data=await api('/api/moments/candidates?'+new URLSearchParams({mid,index,offset}));momentPicker={mid,index,offset:offset+data.items.length};modalType='moment-images';showModal('确认朋友圈缓存图片',`<p class="modal-description">以下图片未重绘或二次压缩，但可能是微信保存的缩略缓存。尺寸相同的排在前面，仅供查找，不代表属于这条动态，请核对画面后选择。</p><div class="moment-picker">${data.items.map(x=>`<div><a href="${e(asset(x.asset))}" target="_blank" rel="noopener"><img loading="lazy" src="${e(asset(x.asset))}" alt="本机缓存图片"></a><small>${x.width} × ${x.height}</small>${btn('使用这张图片','moment-bind','small','',`data-asset="${e(x.asset)}"`)}</div>`).join('')||'<p>请先点击同步朋友圈，建立本机图片索引。</p>'}</div>`,(momentPicker.offset<data.total?btn('下一页','moment-pick-more','small'):'')+btn('关闭','close-modal','primary'));}

async function renderMulti(){
 let value,error='';try{value=await api('/api/weixin/multi');}catch(err){error=err.message;}
 $('#content').innerHTML=`<div class="page antirevoke-page">${heading('微信多开','使用当前微信版本对应的多开规则；关闭所有微信进程后写入。',btn('刷新状态','multi-refresh','','refresh'))}<section class="panel settings-section"><h2>${value?`微信 ${e(value.version)}`:'暂时无法识别微信'}</h2><p role="status">${e(error||value.error|| (value.queued?'已预约，等待所有微信进程退出后写入。':value.file_state==='patched'?'多开文件补丁已写入。':'当前尚未安装多开补丁。'))}</p>${value?`<p class="muted">${e(value.path)} · ${value.running?'微信运行中':'微信已退出'}</p><div class="setting-path">${btn('关闭微信后启用多开','multi-enable','primary','check',value.file_state==='patched'?'disabled':'')}${btn('关闭微信后恢复','multi-disable','','refresh',value.file_state==='original'?'disabled':'')}${btn('打开另一个微信','multi-launch','','arrow',value.file_state!=='patched'||value.queued?'disabled':'')}</div>`:''}<p class="muted">补丁应用后重新打开微信，再点击“打开另一个微信”。新窗口需自行登录；每个账号的归档和模型密钥仍按账号分别保存。</p></section></div>`;
}
actions['multi-refresh']=renderMulti;

async function renderAntiRevoke(){
 $('#content').innerHTML=`<div class="page antirevoke-page">${heading('防撤回','关闭微信后应用上游文件补丁。',btn('重新检测','antirevoke-status','','refresh'))}
 <section class="panel settings-section"><div class="section-heading"><h2 id="antirevoke-title">正在检测微信</h2><span class="muted" id="antirevoke-version"></span></div>
 <p id="antirevoke-status" role="status" aria-live="polite">正在识别微信安装文件…</p>
 <div class="setting-row"><div><label>当前微信</label><p id="antirevoke-target">等待检测</p></div></div>
 <div class="setting-row"><div><label>生效验证</label><p>文件写入成功仅代表补丁安装完成。重新打开微信后，请让对方发一条测试消息并撤回，确认消息确实保留。</p></div></div>
 <div class="setting-path">${btn('关闭微信后安装','antirevoke-enable','primary','lock','disabled')}${btn('关闭微信后恢复 / 取消预约','antirevoke-disable','','refresh','disabled')}</div></section>
 <section class="panel settings-section"><h2>使用说明</h2><p>点击安装后，保持拾光运行并正常退出所有微信进程；拾光会先备份原始文件，再应用与当前版本匹配的规则。安装完成后重新打开微信。恢复也需要先退出微信。</p><p>上游完整源码和 GPLv3 许可证已保存在本地；规则来自 <a href="https://github.com/huiyadanli/RevokeMsgPatcher" target="_blank" rel="noopener noreferrer">RevokeMsgPatcher ↗</a>。</p></section></div>`;
 await runAntiRevoke('status');
}
async function runAntiRevoke(action){
 const buttons=$$('[data-action^="antirevoke-"]');buttons.forEach(b=>b.disabled=true);
 const status=$('#antirevoke-status'),title=$('#antirevoke-title');
 if(status)status.textContent='正在检查安装文件与补丁规则…';
 let result=null;
 try{
  result=await api('/api/antirevoke',{action});
  if(status)status.textContent=result.message;
  if(title)title.textContent=result.queued?'等待微信关闭':result.file_state==='patched'?'文件已安装，待撤回实测':'文件可安装';
  const version=$('#antirevoke-version'),target=$('#antirevoke-target');
  if(version)version.textContent=`微信 ${result.version} · 上游规则 ${result.patch_version}`;
  if(target)target.textContent=`${result.running?'微信运行中':'微信已关闭'} · ${result.path}`;
  if(action!=='status')toast(result.message);
 }catch(error){
  if(status)status.textContent=error.message;
  if(title)title.textContent='暂时无法使用';
 }finally{
  buttons.forEach(b=>b.disabled=b.dataset.action==='antirevoke-status'?false:!result|| (b.dataset.action==='antirevoke-enable'?result.file_state==='patched'||result.queued==='patched':result.file_state==='original'&&!result.queued));
 }
}
